#!/bin/sh
# Generated by scripts/generate-installer.mjs for Lazy AWS 0.1.4.
# We support macOS, Ubuntu, Arch Linux, and Omarchy. Users on supported systems
# can use curl or Homebrew. Debian users can also use either, but Debian is not
# supported. Windows is not supported.

set -eu

PRODUCT_NAME='lazyaws'
INSTALL_DIR_RELATIVE='.local/bin'
LATEST_URL='https://lazyaws.xyz/latest.txt'
DOWNLOAD_BASE_URL='https://github.com/capybara-brain346/lazyaws/releases/download'
CONNECT_TIMEOUT_SECONDS='10'
DOWNLOAD_TIMEOUT_SECONDS='120'
MINIMUM_UBUNTU_VERSION='24.04'
MINIMUM_MACOS_VERSION='15.0'

die() {
  printf '%s: %s\n' "$PRODUCT_NAME" "$*" >&2
  exit 1
}

valid_version() {
  case "$1" in
    v*) version_body=${1#v} ;;
    *) return 1 ;;
  esac
  case "$version_body" in
    ''|*[!0-9.]*|.*|*.|*..*) return 1 ;;
  esac
  old_ifs=$IFS
  IFS=.
  set -- $version_body
  IFS=$old_ifs
  [ "$#" -eq 3 ]
}

version_at_least() {
  awk -v actual="$1" -v minimum="$2" '
    function version_parts(value, parts, count, i) {
      count = split(value, parts, "\\.")
      if (count < 1 || count > 3) return 0
      for (i = 1; i <= count; i++) if (parts[i] !~ /^[0-9]+$/) return 0
      return count
    }
    BEGIN {
      actual_count = version_parts(actual, actual_parts)
      minimum_count = version_parts(minimum, minimum_parts)
      if (!actual_count || !minimum_count) exit 2
      for (i = 1; i <= 3; i++) {
        actual_part = i <= actual_count ? actual_parts[i] + 0 : 0
        minimum_part = i <= minimum_count ? minimum_parts[i] + 0 : 0
        if (actual_part > minimum_part) exit 0
        if (actual_part < minimum_part) exit 1
      }
      exit 0
    }
  '
}

download() {
  case "$1" in
    https://*) ;;
    *) die "Refusing a non-HTTPS download URL." ;;
  esac
  if ! curl -fsSL \
    --connect-timeout "$CONNECT_TIMEOUT_SECONDS" \
    --max-time "$DOWNLOAD_TIMEOUT_SECONDS" \
    --proto '=https' --proto-redir '=https' \
    -o "$2" "$1"; then
    die "Download failed. Check the URL and your network connection."
  fi
}

if [ "$#" -gt 1 ]; then
  die "Usage: sh install.sh [vX.Y.Z]"
fi
if [ "$#" -eq 1 ]; then
  version=$1
  valid_version "$version" || die "Version must use the form vX.Y.Z."
fi

system=$(uname -s) || die "Could not detect the operating system."
machine=$(uname -m) || die "Could not detect the CPU architecture."
case "$system:$machine" in
  Darwin:arm64|Darwin:aarch64) system=darwin; arch=arm64 ;;
  Darwin:x86_64|Darwin:amd64) system=darwin; arch=x86_64 ;;
  Linux:aarch64|Linux:arm64) system=linux; arch=aarch64 ;;
  Linux:x86_64|Linux:amd64) system=linux; arch=x86_64 ;;
  Darwin:*|Linux:*) die "No release supports this CPU architecture: $machine." ;;
  *) die "This operating system is not supported: $system." ;;
esac

if [ "$system" = darwin ]; then
  command -v sw_vers >/dev/null 2>&1 || die "Cannot read the macOS version."
  os_version=$(sw_vers -productVersion) || die "Cannot read the macOS version."
  version_at_least "$os_version" "$MINIMUM_MACOS_VERSION" || \
    die "macOS $MINIMUM_MACOS_VERSION or later is required; found $os_version."
else
  [ -r /etc/os-release ] || die "Cannot identify this Linux distribution."
  os_id=$(awk -F= '$1 == "ID" { gsub(/"/, "", $2); print $2; exit }' /etc/os-release)
  case "$os_id" in
    ubuntu)
      os_version=$(awk -F= '$1 == "VERSION_ID" { gsub(/"/, "", $2); print $2; exit }' /etc/os-release)
      version_at_least "$os_version" "$MINIMUM_UBUNTU_VERSION" || \
        die "Ubuntu $MINIMUM_UBUNTU_VERSION or later is required; found $os_version."
      ;;
    debian)
      printf '%s\n' "$PRODUCT_NAME: Debian is unsupported; installation is best effort." >&2
      ;;
    # shortcut: Arch derivatives that report ID=arch are indistinguishable, when a reliable OS marker exists.
    arch|omarchy)
      [ "$arch" = x86_64 ] || die "Arch Linux and Omarchy require a supported x86_64 build."
      command -v pacman >/dev/null 2>&1 || die "Arch Linux and Omarchy require pacman."
      ;;
    *)
      die "This Linux distribution is not supported: ${os_id:-unknown}."
      ;;
  esac
fi

case "$system:$arch" in
  'darwin:arm64') target='aarch64-apple-darwin' ;;
  'darwin:x86_64') target='x86_64-apple-darwin' ;;
  'linux:aarch64') target='aarch64-unknown-linux-gnu' ;;
  'linux:x86_64') target='x86_64-unknown-linux-gnu' ;;
  *) die "No release archive supports this operating system and CPU." ;;
esac

if [ "${LAZYAWS_INSTALL_DIR+x}" = x ]; then
  [ -n "$LAZYAWS_INSTALL_DIR" ] || die "LAZYAWS_INSTALL_DIR must name a directory."
  install_dir=$LAZYAWS_INSTALL_DIR
else
  [ -n "${HOME:-}" ] || die "HOME is not set; set LAZYAWS_INSTALL_DIR."
  install_dir=$HOME/$INSTALL_DIR_RELATIVE
fi
mkdir -p "$install_dir" || die "Cannot create the install directory: $install_dir"
install_dir=$(CDPATH= cd -P "$install_dir" 2>/dev/null && pwd -P) || \
  die "Cannot access the install directory."
destination=$install_dir/$PRODUCT_NAME

if command -v brew >/dev/null 2>&1; then
  brew_prefix=$(brew --prefix 2>/dev/null) || die "Cannot check the Homebrew install path."
  [ -n "$brew_prefix" ] || die "Cannot check the Homebrew install path."
  brew_prefix=$(CDPATH= cd -P "$brew_prefix" 2>/dev/null && pwd -P) || \
    die "Cannot check the Homebrew install path."
  case "$install_dir" in
    "$brew_prefix"|"$brew_prefix"/*)
      die "Choose an install directory outside Homebrew's prefix."
      ;;
  esac
fi

if [ -L "$destination" ]; then
  die "Refusing to replace a symbolic link: $destination"
fi
if [ -e "$destination" ] && [ ! -f "$destination" ]; then
  die "Refusing to replace a non-file path: $destination"
fi
if [ -f "$destination" ] && command -v pacman >/dev/null 2>&1 && \
  pacman -Qo "$destination" >/dev/null 2>&1; then
  die "Refusing to replace a pacman-managed file: $destination"
fi

umask 077
tmp_dir=$(mktemp -d "${TMPDIR:-/tmp}/lazyaws-install.XXXXXX") || \
  die "Cannot create a private temporary directory."
staged_file=
cleanup() {
  rm -rf "$tmp_dir"
  if [ -n "$staged_file" ]; then rm -f "$staged_file"; fi
}
trap cleanup 0
trap 'exit 1' HUP INT TERM

if [ "$#" -eq 0 ]; then
  download "$LATEST_URL" "$tmp_dir/latest.txt"
  version=$(awk 'NR == 1 { print } END { if (NR != 1) exit 1 }' "$tmp_dir/latest.txt") || \
    die "The latest version response is invalid."
  valid_version "$version" || die "The latest version response is invalid."
fi

archive=${PRODUCT_NAME}-${version}-${target}.tar.gz
release_url=${DOWNLOAD_BASE_URL}/${version}
download "$release_url/SHA256SUMS" "$tmp_dir/SHA256SUMS"
download "$release_url/$archive" "$tmp_dir/$archive"

expected_checksum=$(awk -v expected="$archive" '
  {
    if (length($0) == 66 + length(expected) && substr($0, 65, 2) == "  " &&
        substr($0, 67) == expected && substr($0, 1, 64) !~ /[^[:xdigit:]]/) {
      if (found) exit 1
      checksum = tolower(substr($0, 1, 64))
      found = 1
    }
  }
  END { if (!found) exit 1; print checksum }
' "$tmp_dir/SHA256SUMS") || die "SHA256SUMS has no valid entry for $archive."

# A checksum from the same host detects damage but does not authenticate a compromised host.
if command -v sha256sum >/dev/null 2>&1; then
  checksum_output=$(sha256sum "$tmp_dir/$archive") || die "Cannot calculate the archive checksum."
elif command -v shasum >/dev/null 2>&1; then
  checksum_output=$(shasum -a 256 "$tmp_dir/$archive") || die "Cannot calculate the archive checksum."
else
  die "Install sha256sum or shasum to verify the archive."
fi
actual_checksum=${checksum_output%% *}
[ "${#actual_checksum}" -eq 64 ] || die "Cannot calculate the archive checksum."
[ "$actual_checksum" = "$expected_checksum" ] || die "SHA-256 checksum mismatch."

if ! tar -tzf "$tmp_dir/$archive" > "$tmp_dir/archive.list" || \
  ! tar -tvzf "$tmp_dir/$archive" > "$tmp_dir/archive.details"; then
  die "The downloaded archive is invalid."
fi
if ! awk -v executable="$PRODUCT_NAME" '
  BEGIN { expected[executable] = 1; expected["LICENSE"] = 1; expected["README.txt"] = 1 }
  FNR == NR {
    if (!($0 in expected)) invalid = 1
    listed[$0]++
    next
  }
  {
    name = $NF
    if (substr($0, 1, 1) != "-" || !(name in expected)) invalid = 1
    details[name]++
  }
  END {
    for (name in expected) if (listed[name] != 1 || details[name] != 1) invalid = 1
    if (invalid) exit 1
  }
' "$tmp_dir/archive.list" "$tmp_dir/archive.details"; then
  die "The archive must contain regular root files: lazyaws, LICENSE, and README.txt."
fi

mkdir "$tmp_dir/extracted" || die "Cannot create an extraction directory."
if ! tar -xzf "$tmp_dir/$archive" -C "$tmp_dir/extracted" "$PRODUCT_NAME"; then
  die "Cannot extract the lazyaws executable."
fi
executable=$tmp_dir/extracted/$PRODUCT_NAME
if [ ! -f "$executable" ] || [ -L "$executable" ] || [ ! -x "$executable" ]; then
  die "The archive does not contain a regular executable named lazyaws."
fi
installed_version=$("$executable" --version 2>/dev/null) || die "The downloaded executable failed its version check."
expected_version="$PRODUCT_NAME ${version#v}"
[ "$installed_version" = "$expected_version" ] || \
  die "The downloaded executable reported an unexpected version."

staged_file=$(mktemp "$install_dir/.$PRODUCT_NAME.XXXXXX") || \
  die "Cannot stage the new executable in the install directory."
cp "$executable" "$staged_file" || die "Cannot stage the new executable."
chmod 755 "$staged_file" || die "Cannot make the new executable runnable."
mv -f "$staged_file" "$destination" || die "Cannot replace $destination."
staged_file=

printf 'Installed %s %s at %s\n' "$PRODUCT_NAME" "${version#v}" "$destination"
case ":${PATH:-}:" in
  *:"$install_dir":*) ;;
  *) printf 'Add %s to PATH to run %s.\n' "$install_dir" "$PRODUCT_NAME" ;;
esac
